(6800077, 1021883, 59029, '<td valign="top">nice shot!  I see kingfishers all the time in flight and they''re just too fast to get a good shot, so don''t mind seeing a percher this time round :-)</td>', 'nice shot!  I see kingfishers all the time in flight and they''re just too fast to get a good shot, so don''t mind seeing a percher this time round :-)', '2012-06-22 09:50:03.000000', NULL, 1),
(6800078, 1022157, 43774, '<td valign="top">Great colours and DOF</td>', 'Great colours and DOF', '2012-06-22 09:50:06.000000', NULL, 1),
(6800079, 1021867, 43774, '<td valign="top">Can''t vote but I''d love to.....love this photo, the expression on the mouse''s face is hilarious!!</td>', 'Can''t vote but I''d love to.....love this photo, the expression on the mouse''s face is hilarious!!', '2012-06-22 09:50:49.000000', NULL, 1),
(6800080, 1022324, 43774, '<td valign="top">Looks a little underexposed. Nice setting for the lorikeet.</td>', 'Looks a little underexposed. Nice setting for the lorikeet.', '2012-06-22 09:51:08.000000', NULL, 1),
(6800082, 1022031, 43774, '<td valign="top">Beautiful</td>', 'Beautiful', '2012-06-22 09:52:08.000000', NULL, 1),
(6800083, 1022345, 54446, '<td valign="top">Pretty good image of a Red-breasted Nuthatch.  Great eye-catch glint and feather detail.</td>', 'Pretty good image of a Red-breasted Nuthatch.  Great eye-catch glint and feather detail.', '2012-06-22 09:52:40.000000', NULL, 1),
(6800086, 1021896, 43774, '<td valign="top">Very nice but did you edit the background separately from the bird/tree? I can see a slight halo around everything.</td>', 'Very nice but did you edit the background separately from the bird/tree? I can see a slight halo around everything.', '2012-06-22 09:54:20.000000', NULL, 1),
(6800088, 1022085, 43774, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2012-06-22 09:54:55.000000', NULL, 1),
(6800090, 1021316, 43774, '<td valign="top">Way overprocessed.</td>', 'Way overprocessed.', '2012-06-22 09:55:12.000000', NULL, 1),
(6800091, 1022243, 43774, '<td valign="top">So cute!!</td>', 'So cute!!', '2012-06-22 09:55:19.000000', NULL, 1),
(6800119, 1021769, 674, '<td valign="top">very nice art shot would prefer more habitat just my opinion!</td>', 'very nice art shot would prefer more habitat just my opinion!', '2012-06-22 10:44:12.000000', NULL, 1),
(6800131, 1022114, 103142, '<td valign="top">Absolutely gorgeous! Love the tones in this.</td>', 'Absolutely gorgeous! Love the tones in this.', '2012-06-22 11:13:47.000000', NULL, 1),
(6800132, 1021351, 103142, '<td valign="top">Stunning! Beautiful tones. Love the look on his face. I took an extremely quick look last night, and there were 3 or 4 that just hit me over the head. This is one of them. -9-</td>', 'Stunning! Beautiful tones. Love the look on his face. I took an extremely quick look last night, and there were 3 or 4 that just hit me over the head. This is one of them. -9-', '2012-06-22 11:15:31.000000', NULL, 1),
(6800134, 1021607, 103142, '<td valign="top">What an awesome bird! It must be the Jimmy Durante bird! (I also like that the feeder is a bird foot! :) Fun capture!</td>', 'What an awesome bird! It must be the Jimmy Durante bird! (I also like that the feeder is a bird foot! :) Fun capture!', '2012-06-22 11:16:22.000000', NULL, 1),
(6800136, 1021713, 103142, '<td valign="top">Truly awesome capture! What a wonderful find! Is this a mountain bluebird? -9-</td>', 'Truly awesome capture! What a wonderful find! Is this a mountain bluebird? -9-', '2012-06-22 11:17:11.000000', NULL, 1),
(6800137, 1022286, 103142, '<td valign="top">What a great splash! Fun capture! -8-</td>', 'What a great splash! Fun capture! -8-', '2012-06-22 11:17:59.000000', NULL, 1),
(6800161, 1022281, 142473, '<td valign="top">Incredible clarity, good composition, wonderful colors, great bokeh.  A winner for sure.  I would like to know how you were able to achieve this.</td>', 'Incredible clarity, good composition, wonderful colors, great bokeh.  A winner for sure.  I would like to know how you were able to achieve this.', '2012-06-22 11:51:51.000000', NULL, 1),
(6800166, 1022281, 42256, '<td valign="top">Stopped me and made me go wow!</td>', 'Stopped me and made me go wow!', '2012-06-22 12:12:46.000000', NULL, 1),
(6800171, 1022177, 19825, '<td valign="top">Nice shot. It looks like the bird nickyb and ozmaster ribboned with back in February. Only with a haircut.</td>', 'Nice shot. It looks like the bird nickyb and ozmaster ribboned with back in February. Only with a haircut.', '2012-06-22 12:16:32.000000', NULL, 1),
(6800172, 1021652, 19825, '<td valign="top">Chasing ribbons now? Nice shot.</td>', 'Chasing ribbons now? Nice shot.', '2012-06-22 12:17:53.000000', NULL, 1),
(6800175, 1021651, 19825, '<td valign="top">Yikes. I expect they will get cuter.</td>', 'Yikes. I expect they will get cuter.', '2012-06-22 12:20:49.000000', NULL, 1),
(6800197, 1022294, 103142, '<td valign="top">Absolutely awesome capture! Wonderful colors. Great composition. Beautifully done!</td>', 'Absolutely awesome capture! Wonderful colors. Great composition. Beautifully done!', '2012-06-22 12:57:53.000000', NULL, 1),
(6800198, 1022315, 103142, '<td valign="top">Awesome capture!! I love flickers!</td>', 'Awesome capture!! I love flickers!', '2012-06-22 12:58:56.000000', NULL, 1),
(6800200, 1021796, 103142, '<td valign="top">I really like the shot, but it suffers from the processing. 6</td>', 'I really like the shot, but it suffers from the processing. 6', '2012-06-22 12:59:54.000000', NULL, 1),
(6800201, 1021341, 103142, '<td valign="top">Fun capture!</td>', 'Fun capture!', '2012-06-22 13:00:39.000000', NULL, 1),
(6800204, 1022309, 103142, '<td valign="top">Oooh! I love grey cat birds. What a great capture!</td>', 'Oooh! I love grey cat birds. What a great capture!', '2012-06-22 13:01:58.000000', NULL, 1),
(6800205, 1021909, 103142, '<td valign="top">Stunning!</td>', 'Stunning!', '2012-06-22 13:02:10.000000', NULL, 1),
(6800206, 1021652, 103142, '<td valign="top">Absolutely love this!</td>', 'Absolutely love this!', '2012-06-22 13:02:46.000000', NULL, 1),
(6800207, 1022177, 103142, '<td valign="top">Excellent capture!</td>', 'Excellent capture!', '2012-06-22 13:03:00.000000', NULL, 1),
(6800208, 1022281, 103142, '<td valign="top">Stunning!</td>', 'Stunning!', '2012-06-22 13:03:19.000000', NULL, 1),
