INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6800218, 1021498, 118154, '<td valign="top">He looks a little awkward.</td>', 'He looks a little awkward.', '2012-06-22 13:12:02.000000', NULL, 1),
(6800223, 1021652, 118154, '<td valign="top">Although not the most obvious  of shots in this challenge in my view it has the most feeling and overall pleasure giving of them all.</td>', 'Although not the most obvious  of shots in this challenge in my view it has the most feeling and overall pleasure giving of them all.', '2012-06-22 13:20:17.000000', NULL, 1),
(6800224, 1022177, 118154, '<td valign="top">This is just superb.8.</td>', 'This is just superb.8.', '2012-06-22 13:20:43.000000', NULL, 1),
(6800225, 1021909, 118154, '<td valign="top">Another cracker in my view.8.</td>', 'Another cracker in my view.8.', '2012-06-22 13:21:06.000000', NULL, 1),
(6800226, 1022294, 118154, '<td valign="top">A fine image no doubt.</td>', 'A fine image no doubt.', '2012-06-22 13:21:32.000000', NULL, 1),
(6800228, 1022281, 118154, '<td valign="top">Love the action in this image,one of my topsters.</td>', 'Love the action in this image,one of my topsters.', '2012-06-22 13:22:32.000000', NULL, 1),
(6800229, 1021867, 118154, '<td valign="top">Certainly one of my topsters.</td>', 'Certainly one of my topsters.', '2012-06-22 13:22:56.000000', NULL, 1),
(6800231, 1022040, 118154, '<td valign="top">This is a beautiful image.</td>', 'This is a beautiful image.', '2012-06-22 13:24:19.000000', NULL, 1),
(6800232, 1022363, 118154, '<td valign="top">This is different which gives it a couple more points in my opinion.</td>', 'This is different which gives it a couple more points in my opinion.', '2012-06-22 13:26:09.000000', NULL, 1),
(6800250, 1021896, 65234, '<td valign="top">His (her?) tail looks really short from this angle.  Love the detail and the catchlight in the eye.</td>', 'His (her?) tail looks really short from this angle.  Love the detail and the catchlight in the eye.', '2012-06-22 13:57:49.000000', NULL, 1),
(6800251, 1022361, 65234, '<td valign="top">Looks sort of like a mushroom with a head ;-)</td>', 'Looks sort of like a mushroom with a head ;-)', '2012-06-22 13:58:28.000000', NULL, 1),
(6800253, 1021713, 65234, '<td valign="top">Yummy; bugs!  Beautiful bluebird.</td>', 'Yummy; bugs!  Beautiful bluebird.', '2012-06-22 13:58:49.000000', NULL, 1),
(6800254, 1022333, 65234, '<td valign="top">Isn''t that always the way of things?  You find a good spot and then someone comes along and wants to take it away.  Love the pose of the bird in the background.  Much of the background looks overly noisy on my screen.</td>', 'Isn''t that always the way of things?  You find a good spot and then someone comes along and wants to take it away.  Love the pose of the bird in the background.  Much of the background looks overly noisy on my screen.', '2012-06-22 14:00:57.000000', NULL, 1),
(6800255, 1022281, 65234, '<td valign="top">Yikes; I''d get out of his way!  Beautiful feather detail on those wings.</td>', 'Yikes; I''d get out of his way!  Beautiful feather detail on those wings.', '2012-06-22 14:01:34.000000', NULL, 1),
(6800256, 1022156, 65234, '<td valign="top">Awww :-)  Quite a colorful little bird (Lorikeet?) with a fascinating eye.</td>', 'Awww :-)  Quite a colorful little bird (Lorikeet?) with a fascinating eye.', '2012-06-22 14:02:29.000000', NULL, 1),
(6800257, 1022302, 65234, '<td valign="top">Composition is nice.  Processing is kind of overly watercolor-y for my photographic taste, and the bird''s eye looks vacantly creepy to me.</td>', 'Composition is nice.  Processing is kind of overly watercolor-y for my photographic taste, and the bird''s eye looks vacantly creepy to me.', '2012-06-22 14:03:38.000000', NULL, 1),
(6800259, 1021867, 54446, '<td valign="top">Overall, very good.  7</td>', 'Overall, very good.  7', '2012-06-22 14:04:19.000000', NULL, 1),
(6800260, 1022305, 65234, '<td valign="top">Much cuter than the adults!  Eye is nice and sharp; might like a smidge more DOF to get the beak in focus.</td>', 'Much cuter than the adults!  Eye is nice and sharp; might like a smidge more DOF to get the beak in focus.', '2012-06-22 14:04:32.000000', NULL, 1),
(6800262, 1022243, 65234, '<td valign="top">Or baby is getting yelled at ;-)  Cute scene.</td>', 'Or baby is getting yelled at ;-)  Cute scene.', '2012-06-22 14:05:05.000000', NULL, 1),
(6800265, 1021605, 65234, '<td valign="top">Aw, a baby :-)  I know you probably couldn''t get a better angle but I really want that stick out of his face!</td>', 'Aw, a baby :-)  I know you probably couldn''t get a better angle but I really want that stick out of his face!', '2012-06-22 14:05:51.000000', NULL, 1),
(6800267, 1022156, 54446, '<td valign="top">Wonderful Rainbow Lorikeet.  Magnificent colors, well presented.  It''s okay to have the gentleman in the scene, but it is a distraction from the great bird.  7</td>', 'Wonderful Rainbow Lorikeet.  Magnificent colors, well presented.  It''s okay to have the gentleman in the scene, but it is a distraction from the great bird.  7', '2012-06-22 14:06:22.000000', NULL, 1),
(6800268, 1022251, 65234, '<td valign="top">One of my favorite visitors :-)  Nice and sharp, with good color.  Not an unusual pose, so not a blow-me-away sort of image, but well done.</td>', 'One of my favorite visitors :-)  Nice and sharp, with good color.  Not an unusual pose, so not a blow-me-away sort of image, but well done.', '2012-06-22 14:07:22.000000', NULL, 1),
(6800269, 1021645, 65234, '<td valign="top">Itsy bitsy baby bird!  Very cute.</td>', 'Itsy bitsy baby bird!  Very cute.', '2012-06-22 14:07:58.000000', NULL, 1),
(6800270, 1022298, 65234, '<td valign="top">You would be too if you had red, wrinkly skin all over your face.  Such an odd sort of duck, those Muscovies.</td>', 'You would be too if you had red, wrinkly skin all over your face.  Such an odd sort of duck, those Muscovies.', '2012-06-22 14:08:44.000000', NULL, 1),
(6800275, 1022309, 65234, '<td valign="top">Yum, another bug-eater!  Beautiful Catbird; IMO image might benefit from some noise reduction, or a conversion to B&amp;W (personal thing; I don''t seem to mind noise as much in B&amp;W images).</td>', 'Yum, another bug-eater!  Beautiful Catbird; IMO image might benefit from some noise reduction, or a conversion to B&W (personal thing; I don''t seem to mind noise as much in B&W images).', '2012-06-22 14:10:44.000000', NULL, 1),
(6800282, 1022151, 54446, '<td valign="top">Brown pelicans or American White Pelicans.  I can''t tell for sure.  My guess would be White Pelicans, juvenile.  While I certainly don''t count off the score for my inability to ID, it does point to the difficult lighting on the birds.  Some detail lost in the shadows and the highlights.  Still, a commendable effort.  7</td>', 'Brown pelicans or American White Pelicans.  I can''t tell for sure.  My guess would be White Pelicans, juvenile.  While I certainly don''t count off the score for my inability to ID, it does point to the difficult lighting on the birds.  Some detail lost in the shadows and the highlights.  Still, a commendable effort.  7', '2012-06-22 14:18:05.000000', NULL, 1),
(6800286, 1022289, 54446, '<td valign="top">Red-shouldered hawk, probably.  But, I''d need to see more of the bird to tell for sure.  Some electronic noise on feathers.  I like the beak detail and the eye catch glint.</td>', 'Red-shouldered hawk, probably.  But, I''d need to see more of the bird to tell for sure.  Some electronic noise on feathers.  I like the beak detail and the eye catch glint.', '2012-06-22 14:23:40.000000', NULL, 1),
(6800287, 1022281, 54446, '<td valign="top">I''m sure you''ll hear this a dozen times, but the wings clipped are a distraction.  I do like the action capture and the close up of the head and talons.</td>', 'I''m sure you''ll hear this a dozen times, but the wings clipped are a distraction.  I do like the action capture and the close up of the head and talons.', '2012-06-22 14:23:44.000000', NULL, 1),
(6800289, 1022322, 54446, '<td valign="top">Adult, male, Wood Duck (non breeding).  7</td>', 'Adult, male, Wood Duck (non breeding).  7', '2012-06-22 14:25:39.000000', NULL, 1),
(6800304, 1022309, 54446, '<td valign="top">Outstanding bird behavior presentation.  Some electronic noise on the lower breast which distracts somewhat.  Not enough field marks for me to id the bird, but I note the Assassin beetle.  Overall, very nice effort. 7</td>', 'Outstanding bird behavior presentation.  Some electronic noise on the lower breast which distracts somewhat.  Not enough field marks for me to id the bird, but I note the Assassin beetle.  Overall, very nice effort. 7', '2012-06-22 14:47:53.000000', NULL, 1),
(6800306, 1022251, 54446, '<td valign="top">Nice peek-a-boo shot by the male House Finch.  Good selective focus and superb eye-catch glint.  i''d sure like to have seen more of the body and wings, but very good as presented.  7</td>', 'Nice peek-a-boo shot by the male House Finch.  Good selective focus and superb eye-catch glint.  i''d sure like to have seen more of the body and wings, but very good as presented.  7', '2012-06-22 14:49:43.000000', NULL, 1),
(6800307, 1022197, 54446, '<td valign="top">On images like this, I like the slight motion blur of the wings because it denotes motion.  Super job on the sharpness of the eye, head feathers and gorget.  We don''t have rub-throated HBs in Colorado.  We do have broad-tailed HBs.  Those have a gorget which is more red.  I checked the id books and apps.  Your more orange-red colors are accurate.  7</td>', 'On images like this, I like the slight motion blur of the wings because it denotes motion.  Super job on the sharpness of the eye, head feathers and gorget.  We don''t have rub-throated HBs in Colorado.  We do have broad-tailed HBs.  Those have a gorget which is more red.  I checked the id books and apps.  Your more orange-red colors are accurate.  7', '2012-06-22 14:53:50.000000', NULL, 1),
(6800308, 1022250, 54446, '<td valign="top">Exotic bird to me.  Love the behavior of the insect capture.  The eye catch glint is sharp, which carries the image.  7</td>', 'Exotic bird to me.  Love the behavior of the insect capture.  The eye catch glint is sharp, which carries the image.  7', '2012-06-22 14:55:09.000000', NULL, 1),
(6800309, 1022290, 54446, '<td valign="top">Could be from somewhere other than North America, which is fine.  If this bird is from North America, then it''s likely a juvenile Black-crowned Night-Heron.  Love the eye and the foot.  7</td>', 'Could be from somewhere other than North America, which is fine.  If this bird is from North America, then it''s likely a juvenile Black-crowned Night-Heron.  Love the eye and the foot.  7', '2012-06-22 14:59:21.000000', NULL, 1),
(6800310, 1022243, 54446, '<td valign="top">Northern Gannet.  Fine image showing lots of bird behavior.  9</td>', 'Northern Gannet.  Fine image showing lots of bird behavior.  9', '2012-06-22 15:00:08.000000', NULL, 1),
(6800314, 1022090, 54446, '<td valign="top">Mute Swans.  Tilted view works pretty well.  Good ripples and reflections.  Pretty good control of the white highlights, which is not easy in sunlight. 7</td>', 'Mute Swans.  Tilted view works pretty well.  Good ripples and reflections.  Pretty good control of the white highlights, which is not easy in sunlight. 7', '2012-06-22 15:03:49.000000', NULL, 1),
(6800315, 1022031, 49954, '<td valign="top">Oh so very sweet...</td>', 'Oh so very sweet...', '2012-06-22 15:04:07.000000', NULL, 1),
(6800316, 1022040, 49954, '<td valign="top">Wow...</td>', 'Wow...', '2012-06-22 15:04:34.000000', NULL, 1),
(6800317, 1022363, 54446, '<td valign="top">Wow!  Unique POV of this Canada Goose.    Those are big fish.   7</td>', 'Wow!  Unique POV of this Canada Goose.    Those are big fish.   7', '2012-06-22 15:04:37.000000', NULL, 1),
(6800319, 1022361, 54446, '<td valign="top">Difficult dappled light.  Good job.  Sort of a posterior view, but I like the image.  7</td>', 'Difficult dappled light.  Good job.  Sort of a posterior view, but I like the image.  7', '2012-06-22 15:07:35.000000', NULL, 1),
(6800320, 1022294, 92577, '<td valign="top">Ouch! That''s amazing.</td>', 'Ouch! That''s amazing.', '2012-06-22 15:08:45.000000', NULL, 1),
(6800322, 1022151, 92577, '<td valign="top"><strike></strike></td>', '', '2012-06-22 15:11:35.000000', NULL, 1),
(6800323, 1021769, 49954, '<td valign="top">Wow... winner!</td>', 'Wow... winner!', '2012-06-22 15:11:37.000000', NULL, 1),
(6800334, 1021601, 138253, '<td valign="top">The only entry that made me laugh.<br/>good job</td>', 'The only entry that made me laugh.good job', '2012-06-22 15:47:17.000000', NULL, 1),
(6800340, 1021769, 35602, '<td valign="top">This is too gorgeous.  I am amazed how people get these shots.  10</td>', 'This is too gorgeous.  I am amazed how people get these shots.  10', '2012-06-22 16:17:49.000000', NULL, 1),
(6800341, 1022152, 35602, '<td valign="top">I love ibis''s and egrets.  Nice treatment with the blue.  That made an ordinary shot become extraordinary.</td>', 'I love ibis''s and egrets.  Nice treatment with the blue.  That made an ordinary shot become extraordinary.', '2012-06-22 16:19:59.000000', NULL, 1),
(6800342, 1021670, 35602, '<td valign="top">Nice photo.</td>', 'Nice photo.', '2012-06-22 16:20:50.000000', NULL, 1),
(6800343, 1021796, 35602, '<td valign="top">Love the light.</td>', 'Love the light.', '2012-06-22 16:21:23.000000', NULL, 1),
(6800346, 1022333, 35602, '<td valign="top">Needed a higher shutter speed.  These guys are really hard to get a decent shot of.</td>', 'Needed a higher shutter speed.  These guys are really hard to get a decent shot of.', '2012-06-22 16:23:27.000000', NULL, 1),
(6800348, 1021774, 35602, '<td valign="top">Excellent clarity and detail.  Nice pose.</td>', 'Excellent clarity and detail.  Nice pose.', '2012-06-22 16:25:11.000000', NULL, 1),
(6800349, 1022324, 35602, '<td valign="top">Very confusing colors.  The brd is nearly camouflaged.  Perhaps more brightness and a color curve adjustment.</td>', 'Very confusing colors.  The brd is nearly camouflaged.  Perhaps more brightness and a color curve adjustment.', '2012-06-22 16:26:47.000000', NULL, 1),
(6800350, 1022294, 54446, '<td valign="top">Great Blue Heron with a nice catch.  Well composed with good detail.  7</td>', 'Great Blue Heron with a nice catch.  Well composed with good detail.  7', '2012-06-22 16:27:10.000000', NULL, 1),
(6800351, 1021268, 35602, '<td valign="top">Cute.  Very interesting shadow composition.</td>', 'Cute.  Very interesting shadow composition.', '2012-06-22 16:28:00.000000', NULL, 1),
(6800353, 1021652, 54446, '<td valign="top">Love your treatment of this image.  Has a very nice nostalgic feel.  Well done! 8</td>', 'Love your treatment of this image.  Has a very nice nostalgic feel.  Well done! 8', '2012-06-22 16:28:08.000000', NULL, 1),
(6800354, 1022032, 54446, '<td valign="top">Pretty good domestic rooster.  Great detail of the hed and feathers.  It''s cropped plenty tight and you''ve clipped some parts (feet, tail).   But, a very commendable effort.  7</td>', 'Pretty good domestic rooster.  Great detail of the hed and feathers.  It''s cropped plenty tight and you''ve clipped some parts (feet, tail).   But, a very commendable effort.  7', '2012-06-22 16:29:44.000000', NULL, 1),
(6800355, 1022371, 54446, '<td valign="top">Beautiful closeup with fine detail.  7</td>', 'Beautiful closeup with fine detail.  7', '2012-06-22 16:30:15.000000', NULL, 1),
(6800357, 1021652, 35602, '<td valign="top">Not sure if this is a live photo, or one of a painting.   It begs one to really scrutinize.  I guess it is a motion photo.  Very different style.</td>', 'Not sure if this is a live photo, or one of a painting.   It begs one to really scrutinize.  I guess it is a motion photo.  Very different style.', '2012-06-22 16:30:47.000000', NULL, 1),
(6800358, 1021341, 35602, '<td valign="top">Great title.  I would have cropped more from the right.  It doesn''t add anything to the image.</td>', 'Great title.  I would have cropped more from the right.  It doesn''t add anything to the image.', '2012-06-22 16:31:54.000000', NULL, 1),
(6800359, 1022119, 35602, '<td valign="top">Not liking the silhouette.  Cuts the pic in half.</td>', 'Not liking the silhouette.  Cuts the pic in half.', '2012-06-22 16:33:30.000000', NULL, 1),
(6800360, 1022072, 35602, '<td valign="top">Too much uninteresting sky.</td>', 'Too much uninteresting sky.', '2012-06-22 16:34:44.000000', NULL, 1),
(6800363, 1021680, 35602, '<td valign="top">Zoom of background is nice, but the gull needs to be more focused.  Did you use a lensbaby?</td>', 'Zoom of background is nice, but the gull needs to be more focused.  Did you use a lensbaby?', '2012-06-22 16:36:54.000000', NULL, 1),
(6800364, 1022365, 35602, '<td valign="top">Great prop.  Did you coax him there with a little food in the armor?  Good effort for the challenge.</td>', 'Great prop.  Did you coax him there with a little food in the armor?  Good effort for the challenge.', '2012-06-22 16:38:46.000000', NULL, 1),
(6800366, 1022249, 35602, '<td valign="top">Huh?  Wow that is some camouflage.</td>', 'Huh?  Wow that is some camouflage.', '2012-06-22 16:41:48.000000', NULL, 1),
(6800367, 1021950, 35602, '<td valign="top">Very moody pic.  The moonlit look works quite well.</td>', 'Very moody pic.  The moonlit look works quite well.', '2012-06-22 16:43:39.000000', NULL, 1),
(6800368, 1021338, 35602, '<td valign="top">Sorry, could be sust on the camera.  Should have tried harder.</td>', 'Sorry, could be sust on the camera.  Should have tried harder.', '2012-06-22 16:44:25.000000', NULL, 1),
(6800369, 1021685, 35602, '<td valign="top">Probably would look better LARGE!!!  Majestic bit of rock.  Are they condors?</td>', 'Probably would look better LARGE!!!  Majestic bit of rock.  Are they condors?', '2012-06-22 16:45:42.000000', NULL, 1),
(6800370, 1022184, 35602, '<td valign="top">Very cute.  Need a little smile now and again, and this one got one.  Thanks for the comic relief.</td>', 'Very cute.  Need a little smile now and again, and this one got one.  Thanks for the comic relief.', '2012-06-22 16:48:38.000000', NULL, 1),
(6800387, 1021607, 54446, '<td valign="top">Great colors.  A tropical toucan type bird.  Magnificent detail on the bill.  7</td>', 'Great colors.  A tropical toucan type bird.  Magnificent detail on the bill.  7', '2012-06-22 17:26:45.000000', NULL, 1),
(6800390, 1022031, 54446, '<td valign="top">Mute swan with cygnet.  Good effort to control the bright highlights of the white feathers in the sun.  The background is sort of overwhelmingly dark, but that''s what it takes.  7</td>', 'Mute swan with cygnet.  Good effort to control the bright highlights of the white feathers in the sun.  The background is sort of overwhelmingly dark, but that''s what it takes.  7', '2012-06-22 17:29:37.000000', NULL, 1),
(6800391, 1022328, 54446, '<td valign="top">Gorgeous colors and feather detail.  7</td>', 'Gorgeous colors and feather detail.  7', '2012-06-22 17:30:01.000000', NULL, 1),
(6800392, 1021814, 54446, '<td valign="top">Very cute Atlantic Puffin.  The ocean water undulations are beautiful blue, but the ocean is probably too much a proportion of the scene vs. the bird.  Natural colors.  Would like to see a bit more detail in the bird.  The reflection in the water adds interest.  7</td>', 'Very cute Atlantic Puffin.  The ocean water undulations are beautiful blue, but the ocean is probably too much a proportion of the scene vs. the bird.  Natural colors.  Would like to see a bit more detail in the bird.  The reflection in the water adds interest.  7', '2012-06-22 17:32:24.000000', NULL, 1),
(6800393, 1022370, 54446, '<td valign="top">That''s the way I see them most of the time.  They don''t tolerate me walking up close.  Nice freeze of the action.  Good background.  Midday sunlight makes the scene a little harsh in lighting, but that''s what gave you the fast shutter speed to get the detail.  7</td>', 'That''s the way I see them most of the time.  They don''t tolerate me walking up close.  Nice freeze of the action.  Good background.  Midday sunlight makes the scene a little harsh in lighting, but that''s what gave you the fast shutter speed to get the detail.  7', '2012-06-22 17:33:45.000000', NULL, 1),
(6800395, 1022137, 54446, '<td valign="top">Common grackle and immature.  Classic juvenile begging behavior.  Natural colors.  Could use a little more detail in the feathers.  7</td>', 'Common grackle and immature.  Classic juvenile begging behavior.  Natural colors.  Could use a little more detail in the feathers.  7', '2012-06-22 17:35:29.000000', NULL, 1),
(6800396, 1022157, 54446, '<td valign="top">Rainbow Lorikeets, I think.  Nice pair and interesting poses.  7</td>', 'Rainbow Lorikeets, I think.  Nice pair and interesting poses.  7', '2012-06-22 17:36:21.000000', NULL, 1),
(6800399, 1021883, 65234, '<td valign="top">Love the light, detail, and color.  Great portrait.</td>', 'Love the light, detail, and color.  Great portrait.', '2012-06-22 17:39:36.000000', NULL, 1),
(6800400, 1022318, 54446, '<td valign="top">Little Blue Heron.  Nice shot, as in good capture of hunting motion.  7</td>', 'Little Blue Heron.  Nice shot, as in good capture of hunting motion.  7', '2012-06-22 17:39:39.000000', NULL, 1),
(6800401, 1022031, 65234, '<td valign="top">Beautiful scene and processing creates a gentle mood.  Lovely.</td>', 'Beautiful scene and processing creates a gentle mood.  Lovely.', '2012-06-22 17:40:19.000000', NULL, 1),
(6800403, 1021867, 65234, '<td valign="top">Not a pretty image, but it sure tells a story!  In graphic detail, as it were.  Well done, even if it does make me feel sorry for the rodent.</td>', 'Not a pretty image, but it sure tells a story!  In graphic detail, as it were.  Well done, even if it does make me feel sorry for the rodent.', '2012-06-22 17:41:58.000000', NULL, 1),
(6800404, 1021769, 65234, '<td valign="top">STUNNING reflection with that pose.</td>', 'STUNNING reflection with that pose.', '2012-06-22 17:43:09.000000', NULL, 1),
(6800405, 1021498, 54446, '<td valign="top">Most of the jays like to sit in the shade.  Seems like the background was much brighter originally and you''ve adjusted in PP.  That can be great, but watch the JPG artifacts and the overall effect on the image.  To me, this is a flat image with the BJ looking like it''s been masked out from the background.</td>', 'Most of the jays like to sit in the shade.  Seems like the background was much brighter originally and you''ve adjusted in PP.  That can be great, but watch the JPG artifacts and the overall effect on the image.  To me, this is a flat image with the BJ looking like it''s been masked out from the background.', '2012-06-22 17:43:46.000000', NULL, 1),
(6800407, 1022040, 65234, '<td valign="top">Love the composition and color, and the gorgeous light on that lead bird (who clearly is master of all he surveys).  That bird in the background really makes this image sing to me, though. I can''t explain why, but i wouldn''t like the image as much without it.  Simply beautiful.</td>', 'Love the composition and color, and the gorgeous light on that lead bird (who clearly is master of all he surveys).  That bird in the background really makes this image sing to me, though. I can''t explain why, but i wouldn''t like the image as much without it.  Simply beautiful.', '2012-06-22 17:48:02.000000', NULL, 1),
(6800408, 1022114, 54446, '<td valign="top">Pretty scene with a low angle sun.  The fog over the water is a nice atmospheric effect.  In the northern hemisphere, most birds have completed their migration and are in some stage of nesting or training fledglings.  We don''t see many flocks of migrating birds in June.  So, my guess is this is a southern hemisphere scene, but that is purely a guess.  (probably wrong)</td>', 'Pretty scene with a low angle sun.  The fog over the water is a nice atmospheric effect.  In the northern hemisphere, most birds have completed their migration and are in some stage of nesting or training fledglings.  We don''t see many flocks of migrating birds in June.  So, my guess is this is a southern hemisphere scene, but that is purely a guess.  (probably wrong)', '2012-06-22 17:48:20.000000', NULL, 1),
(6800409, 1022296, 65234, '<td valign="top">Looks like this could be a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=103142" rel="nofollow" target="_blank">Vawendy</a> creation.  And if not, well done for making me think so!  Gorgeous finch, great light, intriguing setup.</td>', 'Looks like this could be a  Vawendy creation.  And if not, well done for making me think so!  Gorgeous finch, great light, intriguing setup.', '2012-06-22 17:50:00.000000', NULL, 1),
(6800410, 1021909, 65234, '<td valign="top">Spectacular, dramatic light.  Looks somewhat like museum lighting, but a striking image regardless.</td>', 'Spectacular, dramatic light.  Looks somewhat like museum lighting, but a striking image regardless.', '2012-06-22 17:51:34.000000', NULL, 1),
(6800411, 1022150, 65234, '<td valign="top">Gorgeous bird!  Beautifully detailed.</td>', 'Gorgeous bird!  Beautifully detailed.', '2012-06-22 17:52:08.000000', NULL, 1),
(6800412, 1022248, 65234, '<td valign="top">Another beautiful bird, well presented.</td>', 'Another beautiful bird, well presented.', '2012-06-22 17:52:41.000000', NULL, 1),
(6800413, 1022157, 65234, '<td valign="top">Fun pose for these colorful characters.</td>', 'Fun pose for these colorful characters.', '2012-06-22 17:53:13.000000', NULL, 1),
(6800414, 1022264, 65234, '<td valign="top">Beautiful portrait.</td>', 'Beautiful portrait.', '2012-06-22 17:53:31.000000', NULL, 1),
(6800415, 1021351, 65234, '<td valign="top">Cool bird; not a species I''m familiar with, I don''t think.  Love that long bill, curvy neck and bright eye.  Well captured.</td>', 'Cool bird; not a species I''m familiar with, I don''t think.  Love that long bill, curvy neck and bright eye.  Well captured.', '2012-06-22 17:54:58.000000', NULL, 1),
(6800416, 1022033, 54446, '<td valign="top">Gulls, but I cannot narrow down the species.  The focus is better on the more distant bird.  Might have been better to have the foreground bird sharply in focus.  Then, the viewer would be more tolerant of the narrow DOF.</td>', 'Gulls, but I cannot narrow down the species.  The focus is better on the more distant bird.  Might have been better to have the foreground bird sharply in focus.  Then, the viewer would be more tolerant of the narrow DOF.', '2012-06-22 17:55:01.000000', NULL, 1),
(6800417, 1022338, 54446, '<td valign="top">Good peak at a domestic rooster.  Some hot spots in the background.  And, you are expecting the viewer to look at and past some big pieces of OOF wood.  I do recognize the sharp focus on the rooster.</td>', 'Good peak at a domestic rooster.  Some hot spots in the background.  And, you are expecting the viewer to look at and past some big pieces of OOF wood.  I do recognize the sharp focus on the rooster.', '2012-06-22 17:56:45.000000', NULL, 1),
(6800418, 1021814, 65234, '<td valign="top">I should not give out bonus points for exceptional cuteness of subject, but ... it''s a Puffin :-))). On the deep blue sea, which both sets him off beautifully and gives an idea of how small he is.  I love Puffins!</td>', 'I should not give out bonus points for exceptional cuteness of subject, but ... it''s a Puffin :-))). On the deep blue sea, which both sets him off beautifully and gives an idea of how small he is.  I love Puffins!', '2012-06-22 17:57:45.000000', NULL, 1),
(6800419, 1022369, 54446, '<td valign="top">The rounded tail would make this a crow.  Had the tail been wedged shaped, it would have been more likely ID''d as a raven.  It''s an interesting in flight motion blur image.  I like it.</td>', 'The rounded tail would make this a crow.  Had the tail been wedged shaped, it would have been more likely ID''d as a raven.  It''s an interesting in flight motion blur image.  I like it.', '2012-06-22 17:58:12.000000', NULL, 1),
(6800420, 1022322, 65234, '<td valign="top">Beautiful Wood Duck.  Nice detail.</td>', 'Beautiful Wood Duck.  Nice detail.', '2012-06-22 17:59:02.000000', NULL, 1),
(6800422, 1022116, 54446, '<td valign="top">Lesser Goldfinch, adult female.  Good capture of her vocalization. There is a slight halo around the perimeter of the bird.   I don''t mind the fence.  The bg is great. Feather detail is good.</td>', 'Lesser Goldfinch, adult female.  Good capture of her vocalization. There is a slight halo around the perimeter of the bird.   I don''t mind the fence.  The bg is great. Feather detail is good.', '2012-06-22 18:01:36.000000', NULL, 1),
(6800423, 1022366, 54446, '<td valign="top">Curious display of moire effect in the water.  Not something one would normally see with one''s eyes. Definitely a distraction for me, but I''m certain some will like the abstract effect.   I like the flamingo.  This image could have been cropped quite a lot to your advantage.</td>', 'Curious display of moire effect in the water.  Not something one would normally see with one''s eyes. Definitely a distraction for me, but I''m certain some will like the abstract effect.   I like the flamingo.  This image could have been cropped quite a lot to your advantage.', '2012-06-22 18:04:16.000000', NULL, 1),
(6800424, 1022030, 54446, '<td valign="top">Pretty tough lighting situation.  Maybe it could have been an opportunity for a fill flash.  Or, just move your feet.  But, I understand the interest in capturing the human/pet interaction.</td>', 'Pretty tough lighting situation.  Maybe it could have been an opportunity for a fill flash.  Or, just move your feet.  But, I understand the interest in capturing the human/pet interaction.', '2012-06-22 18:06:08.000000', NULL, 1),
(6800425, 1021863, 54446, '<td valign="top">Good capture of the full wing spread and tail feather spread as the bird comes in for a landing.  Wow, I really hate the background.  I''m sure you are trying to deal with a dark subject against a bright background.    Pigeons are so common, there must have been a better lighting situation.</td>', 'Good capture of the full wing spread and tail feather spread as the bird comes in for a landing.  Wow, I really hate the background.  I''m sure you are trying to deal with a dark subject against a bright background.    Pigeons are so common, there must have been a better lighting situation.', '2012-06-22 18:08:39.000000', NULL, 1),
(6800428, 1022367, 54446, '<td valign="top">Very difficult (and common) lighting problem.  Bird in the shade is properly exposed.  The sunlit background wildly bright. It''s a great pose.  Good focus.  Great Egret, possibly, but I''d need to see some field marks to know for sure.</td>', 'Very difficult (and common) lighting problem.  Bird in the shade is properly exposed.  The sunlit background wildly bright. It''s a great pose.  Good focus.  Great Egret, possibly, but I''d need to see some field marks to know for sure.', '2012-06-22 18:11:56.000000', NULL, 1),
(6800429, 1022235, 54446, '<td valign="top">A very good closeup of a confined bird with neutral background.  Photographing a confined is okay, as that is the only way some people ever see some birds.  The feather detail, eye detail and beak detail is superb, as one should expect from a bird which cannot flee.</td>', 'A very good closeup of a confined bird with neutral background.  Photographing a confined is okay, as that is the only way some people ever see some birds.  The feather detail, eye detail and beak detail is superb, as one should expect from a bird which cannot flee.', '2012-06-22 18:14:45.000000', NULL, 1),
(6800430, 1021351, 54446, '<td valign="top">Looks a bit like a tricolor heron, but the field marks don''t match.  So, I don''t know the ID of this bird.  Great detail in feathers, eye and beak.</td>', 'Looks a bit like a tricolor heron, but the field marks don''t match.  So, I don''t know the ID of this bird.  Great detail in feathers, eye and beak.', '2012-06-22 18:17:56.000000', NULL, 1),
(6800434, 1022264, 54446, '<td valign="top">Streaked flanks, pale grayish auriculars and curved culmen indicate this is a House Finch.  I could certainly be wrong.  I really like the pose and the oak perch and background.  There are some indications of "jaggies" on the feather edges and tree leaf and stem edges.  Not sure why, but it''s noticable.</td>', 'Streaked flanks, pale grayish auriculars and curved culmen indicate this is a House Finch.  I could certainly be wrong.  I really like the pose and the oak perch and background.  There are some indications of "jaggies" on the feather edges and tree leaf and stem edges.  Not sure why, but it''s noticable.', '2012-06-22 18:27:08.000000', NULL, 1),
(6800435, 1021651, 54446, '<td valign="top">just hatched Lorikeets, perhaps.  It''s an interesting view into their early lives.</td>', 'just hatched Lorikeets, perhaps.  It''s an interesting view into their early lives.', '2012-06-22 18:28:11.000000', NULL, 1),
(6800438, 1022072, 54446, '<td valign="top">Possibly a Eurasian Curlew, but I''ve never seen one.  Lots of negative space, which is somewhat effective composition.  The bird begs to be seen closer.</td>', 'Possibly a Eurasian Curlew, but I''ve never seen one.  Lots of negative space, which is somewhat effective composition.  The bird begs to be seen closer.', '2012-06-22 18:36:09.000000', NULL, 1),
(6800439, 1022297, 54446, '<td valign="top">Great Blue Heron.  Lots of habitat.  The bird is a small portion of the scene, but I do like environmental images.</td>', 'Great Blue Heron.  Lots of habitat.  The bird is a small portion of the scene, but I do like environmental images.', '2012-06-22 18:37:44.000000', NULL, 1),
(6800440, 1021896, 54446, '<td valign="top">Mighty fine osprey.  Super interesting look at the talons and very strong legs and feet.  The eye is great.</td>', 'Mighty fine osprey.  Super interesting look at the talons and very strong legs and feet.  The eye is great.', '2012-06-22 18:38:42.000000', NULL, 1),
(6800441, 1022040, 54446, '<td valign="top">A good guess would be "Franklin''s Gull".  Not enough field marks showing to know for sure.  I like your presentation, although dreamy.   Gives the feel of freedom and soaring.</td>', 'A good guess would be "Franklin''s Gull".  Not enough field marks showing to know for sure.  I like your presentation, although dreamy.   Gives the feel of freedom and soaring.', '2012-06-22 18:40:52.000000', NULL, 1),
(6800442, 1021951, 54446, '<td valign="top">Certainly a Great Egret.  Excellent environmental shot.  Pretty good lighting.</td>', 'Certainly a Great Egret.  Excellent environmental shot.  Pretty good lighting.', '2012-06-22 18:42:17.000000', NULL, 1),
(6800444, 1022178, 54446, '<td valign="top">Nice selective focus.  I don''t know this bird ID.  Good comp.</td>', 'Nice selective focus.  I don''t know this bird ID.  Good comp.', '2012-06-22 18:43:06.000000', NULL, 1),
(6800447, 1021412, 54446, '<td valign="top">The composition is a bit too center middle for me.  Dramatic bird.  I don''t know the ID.</td>', 'The composition is a bit too center middle for me.  Dramatic bird.  I don''t know the ID.', '2012-06-22 18:53:37.000000', NULL, 1),
(6800448, 1022185, 54446, '<td valign="top">This almost works.  The eye and beak need to be one notch sharper to balance he motion blur (or narrow DOF) represented by the wings.</td>', 'This almost works.  The eye and beak need to be one notch sharper to balance he motion blur (or narrow DOF) represented by the wings.', '2012-06-22 18:54:49.000000', NULL, 1),
(6800449, 1021918, 54446, '<td valign="top">Just a bit underexposed for the HB.  Female Ruby-throated.... or female broad-tailed.  The flower is nicely in focus and properly exposed.</td>', 'Just a bit underexposed for the HB.  Female Ruby-throated.... or female broad-tailed.  The flower is nicely in focus and properly exposed.', '2012-06-22 18:56:29.000000', NULL, 1),
(6800450, 1022286, 54446, '<td valign="top">Great egret, probably.  Good behavior shot.  Nice splash.</td>', 'Great egret, probably.  Good behavior shot.  Nice splash.', '2012-06-22 18:57:05.000000', NULL, 1),
(6800453, 1022115, 54446, '<td valign="top">There is nothing wrong with zoo photos.  My constructive critique of this image is the loss of feather detail (and other fine detail throughout).  For a captive bird this close, I''d expect to see some amazing detail.  Might have been a problem with high dynamic range from shadows to highlights.</td>', 'There is nothing wrong with zoo photos.  My constructive critique of this image is the loss of feather detail (and other fine detail throughout).  For a captive bird this close, I''d expect to see some amazing detail.  Might have been a problem with high dynamic range from shadows to highlights.', '2012-06-22 19:01:34.000000', NULL, 1),
(6800454, 1022039, 54446, '<td valign="top">Penguin.  Zoo shot, which is perfectly okay.  Would have liked to see the entire bird.</td>', 'Penguin.  Zoo shot, which is perfectly okay.  Would have liked to see the entire bird.', '2012-06-22 19:05:45.000000', NULL, 1),
(6800455, 1022305, 54446, '<td valign="top">Very cute.  Nice detail on the head feathers and eye.  Soft beak.</td>', 'Very cute.  Nice detail on the head feathers and eye.  Soft beak.', '2012-06-22 19:06:31.000000', NULL, 1),
(6800456, 1022149, 54446, '<td valign="top">Pigeon roost.  I can see the eyes of one of the pigeons.</td>', 'Pigeon roost.  I can see the eyes of one of the pigeons.', '2012-06-22 19:07:07.000000', NULL, 1),
(6800457, 1022298, 54446, '<td valign="top">Somehow, this doesn''t snap to sharp focus.  Interesting detail in the face.</td>', 'Somehow, this doesn''t snap to sharp focus.  Interesting detail in the face.', '2012-06-22 19:08:01.000000', NULL, 1),
(6800458, 1021316, 54446, '<td valign="top">A bit dreary for some reason.  Too center-middle for me.  Tough looking specimen.  Needs a more shallow DOF.</td>', 'A bit dreary for some reason.  Too center-middle for me.  Tough looking specimen.  Needs a more shallow DOF.', '2012-06-22 19:09:18.000000', NULL, 1),
(6800459, 1022333, 54446, '<td valign="top">American Goldfinc, males.  They don''t pose for long.  Very shy, too.  I like the colors in this image.</td>', 'American Goldfinc, males.  They don''t pose for long.  Very shy, too.  I like the colors in this image.', '2012-06-22 19:10:17.000000', NULL, 1),
(6800460, 1022324, 54446, '<td valign="top">A tropical parrot.  This image seems a bit flat and dull to me.  Love the colors, but overall underexposed.  I think you are trying to show to much in this scene, as the background seems cluttered.  I do think the eye and beak of the bird are nicely in focus.</td>', 'A tropical parrot.  This image seems a bit flat and dull to me.  Love the colors, but overall underexposed.  I think you are trying to show to much in this scene, as the background seems cluttered.  I do think the eye and beak of the bird are nicely in focus.', '2012-06-22 19:12:21.000000', NULL, 1),
(6800461, 1022348, 54446, '<td valign="top">Some good feather detail and sharpness below the eye.</td>', 'Some good feather detail and sharpness below the eye.', '2012-06-22 19:13:07.000000', NULL, 1),
(6800462, 1021657, 54446, '<td valign="top">I don''t recognize the birds.  It''s a unique capture of the overhead flight.  The background sky is indigo blue in places and the birds have some bright highlights.  I''d love to see more detail in the birds, but I do appreciate the flock in flight</td>', 'I don''t recognize the birds.  It''s a unique capture of the overhead flight.  The background sky is indigo blue in places and the birds have some bright highlights.  I''d love to see more detail in the birds, but I do appreciate the flock in flight', '2012-06-22 19:16:35.000000', NULL, 1),
(6800466, 1022015, 54446, '<td valign="top">Black-crowned Night-Heron.  Good capture in flight.  Love the wing primaries detail....translucent light coming through.  Would have liked to see more of the face, especially the eye and beak.  But, this is very good photography.  7</td>', 'Black-crowned Night-Heron.  Good capture in flight.  Love the wing primaries detail....translucent light coming through.  Would have liked to see more of the face, especially the eye and beak.  But, this is very good photography.  7', '2012-06-22 19:25:25.000000', NULL, 1),
(6800469, 1021262, 54446, '<td valign="top">I''m sure this bird''s mother loves that face and food target.  Good detail.</td>', 'I''m sure this bird''s mother loves that face and food target.  Good detail.', '2012-06-22 19:26:16.000000', NULL, 1),
(6800470, 1022012, 54446, '<td valign="top">Looks like an Anhinga to me.  Can''t really tell, but that''s what Anhinga''s do.  The profile (especially the tail) look right for an Anhinga.  With the harsh light and high contrast, some detail is lost in the shadows.  But, I like the silhouetted profile, even if I''d prefer to see more bird and less water.</td>', 'Looks like an Anhinga to me.  Can''t really tell, but that''s what Anhinga''s do.  The profile (especially the tail) look right for an Anhinga.  With the harsh light and high contrast, some detail is lost in the shadows.  But, I like the silhouetted profile, even if I''d prefer to see more bird and less water.', '2012-06-22 19:29:59.000000', NULL, 1),
(6800471, 1022285, 54446, '<td valign="top">Gulls.  Not close enough to see detail.  An old rule of thumb for nature photography is to use odd numbers of subjects (1,3,5...etc.).  Just would be more eye-pleasing.</td>', 'Gulls.  Not close enough to see detail.  An old rule of thumb for nature photography is to use odd numbers of subjects (1,3,5...etc.).  Just would be more eye-pleasing.', '2012-06-22 19:31:40.000000', NULL, 1),
(6800472, 1021767, 54446, '<td valign="top">Love the bird.  Super detail in feathers, eye and beak.  Something not eye-pleasing about the background.  Can''t put my finger on it.  Just doesn''t work well with the spectacular subject.</td>', 'Love the bird.  Super detail in feathers, eye and beak.  Something not eye-pleasing about the background.  Can''t put my finger on it.  Just doesn''t work well with the spectacular subject.', '2012-06-22 19:33:37.000000', NULL, 1),
(6800474, 1021835, 54446, '<td valign="top">This would guarantee the birds will show up in this place in the future.  It''s an interesting study in human nature.  I''d like to see more detail in the birds.  I don''t mind the somewhat distant view, but some detail is lost in the shadows.</td>', 'This would guarantee the birds will show up in this place in the future.  It''s an interesting study in human nature.  I''d like to see more detail in the birds.  I don''t mind the somewhat distant view, but some detail is lost in the shadows.', '2012-06-22 19:36:19.000000', NULL, 1),
(6800478, 1021680, 54446, '<td valign="top">Disturbing radial blur treatment of the grass.  The gull looks cut and pasted in.  Focus and feather detail lacking.  Composition is too center-middle.  The exposure is even.</td>', 'Disturbing radial blur treatment of the grass.  The gull looks cut and pasted in.  Focus and feather detail lacking.  Composition is too center-middle.  The exposure is even.', '2012-06-22 19:41:09.000000', NULL, 1),
(6800479, 1022177, 54446, '<td valign="top">Dramatic and awesome face.  I also think it''s effective selective focus.  However, the backgroud horizontal lines are a distraction.</td>', 'Dramatic and awesome face.  I also think it''s effective selective focus.  However, the backgroud horizontal lines are a distraction.', '2012-06-22 19:42:22.000000', NULL, 1),
(6800480, 1021605, 54446, '<td valign="top">An immature.  Lots of clutter preventing a clear view.</td>', 'An immature.  Lots of clutter preventing a clear view.', '2012-06-22 19:43:41.000000', NULL, 1),
(6800482, 1022152, 54446, '<td valign="top">I have trouble getting past the distraction of the lighter vignette.  Maybe this was a very low light situation.</td>', 'I have trouble getting past the distraction of the lighter vignette.  Maybe this was a very low light situation.', '2012-06-22 19:45:33.000000', NULL, 1),
(6800483, 1022302, 54446, '<td valign="top">Feather detail has been lost.</td>', 'Feather detail has been lost.', '2012-06-22 19:46:06.000000', NULL, 1),
(6800484, 1021816, 54446, '<td valign="top">Cute.  Needs better lighting.  Yellow-crested Cockatoo/</td>', 'Cute.  Needs better lighting.  Yellow-crested Cockatoo/', '2012-06-22 19:47:43.000000', NULL, 1),
(6800486, 1022254, 54446, '<td valign="top">female ruby-throated HB.  Pretty good capture at the HB feeder.  Difficult background.</td>', 'female ruby-throated HB.  Pretty good capture at the HB feeder.  Difficult background.', '2012-06-22 19:48:46.000000', NULL, 1),
(6800490, 1021909, 54446, '<td valign="top">Nothing wrong with photographing birds in captivity.  But, the viewer should expect lots of detail on a closeup portrait.  I''m not too excited about the all black bg, but it is dramatic.  The strength of this image is the eye color and detail.  Very nicely done.</td>', 'Nothing wrong with photographing birds in captivity.  But, the viewer should expect lots of detail on a closeup portrait.  I''m not too excited about the all black bg, but it is dramatic.  The strength of this image is the eye color and detail.  Very nicely done.', '2012-06-22 19:51:09.000000', NULL, 1),
(6800491, 1022299, 54446, '<td valign="top">A silhouette image.   Not sure what you wanted us to see.</td>', 'A silhouette image.   Not sure what you wanted us to see.', '2012-06-22 19:53:47.000000', NULL, 1),
(6800492, 1022321, 54446, '<td valign="top">This may be someone else''s art.</td>', 'This may be someone else''s art.', '2012-06-22 19:54:33.000000', NULL, 1),
(6800493, 1022265, 54446, '<td valign="top">Ah, HB in shade with sunlit background.  The other way around will produce better results.</td>', 'Ah, HB in shade with sunlit background.  The other way around will produce better results.', '2012-06-22 19:55:27.000000', NULL, 1),
(6800494, 1021950, 54446, '<td valign="top">Artistic presentation.</td>', 'Artistic presentation.', '2012-06-22 19:55:53.000000', NULL, 1),
(6800495, 1021352, 54446, '<td valign="top">A good closeup of the eye.  Can''t determine species.</td>', 'A good closeup of the eye.  Can''t determine species.', '2012-06-22 19:56:56.000000', NULL, 1),
(6800496, 1021645, 54446, '<td valign="top">That yellow target is important for the adults.</td>', 'That yellow target is important for the adults.', '2012-06-22 19:57:27.000000', NULL, 1),
(6800497, 1022332, 54446, '<td valign="top">Lots of negative space.</td>', 'Lots of negative space.', '2012-06-22 19:57:55.000000', NULL, 1),
(6800500, 1021446, 54446, '<td valign="top">Good vibrant colors.  Needs more feather detail .</td>', 'Good vibrant colors.  Needs more feather detail .', '2012-06-22 19:59:33.000000', NULL, 1),
(6800519, 1022264, 59029, '<td valign="top">uhm sorry, but it''s a house finch...easy to confuse the two.  Still, a very nicely lit shot, tack sharp.  Good work! 6</td>', 'uhm sorry, but it''s a house finch...easy to confuse the two.  Still, a very nicely lit shot, tack sharp.  Good work! 6', '2012-06-22 21:34:42.000000', NULL, 1),
(6800523, 1022265, 108544, '<td valign="top">Good timing on the shot!<br/>I just find the bird too dark. Probably due to backlighting.<br/>For next time, a flash or reflector, could make the difference.<br/>By filling in the scene with light, it will balance the subject and background brightness. <br/>Also showing that beautiful feather detail and colour.<br/>None available in this instant? Over expose the shot. Shoot for the birds brightness level, not the background. It may create a white background, but for me his detail is what''s important.<br/>Good luck!</td>', 'Good timing on the shot!I just find the bird too dark. Probably due to backlighting.For next time, a flash or reflector, could make the difference.By filling in the scene with light, it will balance the subject and background brightness. Also showing that beautiful feather detail and colour.None available in this instant? Over expose the shot. Shoot for the birds brightness level, not the background. It may create a white background, but for me his detail is what''s important.Good luck!', '2012-06-22 21:41:26.000000', NULL, 1),
(6800525, 1021769, 105977, '<td valign="top">not voting.<br/>on yours</td>', 'not voting.on yours', '2012-06-22 21:43:02.000000', NULL, 1),
(6800529, 1022137, 108544, '<td valign="top">Very nice shot!<br/>Love the action of feeding and it looks like you shot lower than standing. Maybe they were on a crest of a hill. Either way, the background just falls away. Boken looks nice too! <br/>Again, great capture!</td>', 'Very nice shot!Love the action of feeding and it looks like you shot lower than standing. Maybe they were on a crest of a hill. Either way, the background just falls away. Boken looks nice too! Again, great capture!', '2012-06-22 21:46:33.000000', NULL, 1),
(6800530, 1021680, 105977, '<td valign="top">it hurts my eyes  but nice picture.</td>', 'it hurts my eyes  but nice picture.', '2012-06-22 21:47:38.000000', NULL, 1),
(6800532, 1022090, 108544, '<td valign="top">Kinda like one of those 3d posters! <br/>Very nice effect with the water! The comp and mirror effect is excellent.<br/>Well done...</td>', 'Kinda like one of those 3d posters! Very nice effect with the water! The comp and mirror effect is excellent.Well done...', '2012-06-22 21:51:01.000000', NULL, 1),
(6800534, 1022365, 105977, '<td valign="top">is to you art</td>', 'is to you art', '2012-06-22 21:52:12.000000', NULL, 1),
(6800546, 1022296, 54446, '<td valign="top">Purple Finch, male.  I assume the bird came for the sunflower seeds and stayed for tea.  Elegant props.  The totally blacked out background is not my favorite thing, but it does create a dramatic presentation and throws focus to the finch.  8</td>', 'Purple Finch, male.  I assume the bird came for the sunflower seeds and stayed for tea.  Elegant props.  The totally blacked out background is not my favorite thing, but it does create a dramatic presentation and throws focus to the finch.  8', '2012-06-22 22:18:00.000000', NULL, 1),
(6800555, 1021769, 143098, '<td valign="top">really great symmetry an awesome shot indeed. My only nit pick might be the amount of vignette.  I''m a fan of vignette, but seems a tad bit dark , that being said it looks as if it might be to hide the distracting elements behind the birds wing in the upper right corner.  Great shot!!</td>', 'really great symmetry an awesome shot indeed. My only nit pick might be the amount of vignette.  I''m a fan of vignette, but seems a tad bit dark , that being said it looks as if it might be to hide the distracting elements behind the birds wing in the upper right corner.  Great shot!!', '2012-06-22 22:33:11.000000', NULL, 1),
(6800613, 1021601, 113412, '<td valign="top">I''m sorry to rate this so low. It is offensive (to me), and I don''t see any photo excellence that redeems it in any way.</td>', 'I''m sorry to rate this so low. It is offensive (to me), and I don''t see any photo excellence that redeems it in any way.', '2012-06-22 23:52:19.000000', NULL, 1),
(6800614, 1022286, 113412, '<td valign="top">Love the action! Pleasing shades of blue, as well.</td>', 'Love the action! Pleasing shades of blue, as well.', '2012-06-22 23:55:09.000000', NULL, 1),
(6800615, 1021769, 113412, '<td valign="top">I think this is my favorite for this challenge. So beautiful! Reminds me of a dancer. Reflection is lovely.</td>', 'I think this is my favorite for this challenge. So beautiful! Reminds me of a dancer. Reflection is lovely.', '2012-06-22 23:55:52.000000', NULL, 1),
(6800616, 1022250, 93171, '<td valign="top">Nice bokeh!</td>', 'Nice bokeh!', '2012-06-22 23:56:32.000000', NULL, 1),
(6800617, 1022305, 113412, '<td valign="top">So sweet! Perfect focus on his head.</td>', 'So sweet! Perfect focus on his head.', '2012-06-22 23:59:06.000000', NULL, 1),
(6800618, 1021605, 93171, '<td valign="top">Oh, man, this would be wonderful if the bird was in focus instead of the grass!  Nice composition, though.</td>', 'Oh, man, this would be wonderful if the bird was in focus instead of the grass!  Nice composition, though.', '2012-06-23 00:02:25.000000', NULL, 1),
(6800624, 1022328, 66384, '<td valign="top">Beautiful color and clarity. And I like the background bokeh.</td>', 'Beautiful color and clarity. And I like the background bokeh.', '2012-06-23 00:32:20.000000', NULL, 1),
(6800625, 1021883, 66384, '<td valign="top">Wow, I''ve found these guys are very hard to capture. Good job.</td>', 'Wow, I''ve found these guys are very hard to capture. Good job.', '2012-06-23 00:34:24.000000', NULL, 1),
(6800627, 1021769, 64929, '<td valign="top">A M A Z I N G !!!</td>', 'A M A Z I N G !!!', '2012-06-23 00:35:43.000000', NULL, 1),
(6800628, 1022030, 66384, '<td valign="top">Aw, they look like good friends! Nice moment captured.</td>', 'Aw, they look like good friends! Nice moment captured.', '2012-06-23 00:36:12.000000', NULL, 1),
(6800629, 1022177, 66384, '<td valign="top">Gorgeous and so dramatic. Awesome shot!</td>', 'Gorgeous and so dramatic. Awesome shot!', '2012-06-23 00:37:33.000000', NULL, 1),
(6800630, 1022264, 64929, '<td valign="top">Really Beautiful shot!</td>', 'Really Beautiful shot!', '2012-06-23 00:38:31.000000', NULL, 1),
(6800631, 1021835, 66384, '<td valign="top">Makes me smile. Love the moment you captured, with the raised hand, and the food in the air.</td>', 'Makes me smile. Love the moment you captured, with the raised hand, and the food in the air.', '2012-06-23 00:40:19.000000', NULL, 1),
(6800632, 1021607, 64929, '<td valign="top">Beautiful!!</td>', 'Beautiful!!', '2012-06-23 00:41:36.000000', NULL, 1),
(6800633, 1021607, 66384, '<td valign="top">Love the colors, and I''ve never seen a bird like that.</td>', 'Love the colors, and I''ve never seen a bird like that.', '2012-06-23 00:41:41.000000', NULL, 1),
(6800634, 1021918, 66384, '<td valign="top">Wow, nice capture, and I like the way the pink of the bee balm is repeated throughout the picture: in the background and in the bird''s wings.</td>', 'Wow, nice capture, and I like the way the pink of the bee balm is repeated throughout the picture: in the background and in the bird''s wings.', '2012-06-23 00:45:01.000000', NULL, 1),
(6800635, 1022031, 64929, '<td valign="top">Lovely!</td>', 'Lovely!', '2012-06-23 00:48:16.000000', NULL, 1),
(6800636, 1022243, 64929, '<td valign="top">VERY Nice!!!</td>', 'VERY Nice!!!', '2012-06-23 00:49:11.000000', NULL, 1),
(6800637, 1022369, 66384, '<td valign="top">Whoa, this reminds me of the Hitchcock movie, ''The Birds''. Rather frightening. Dramatic capture, and nice off-center composition.</td>', 'Whoa, this reminds me of the Hitchcock movie, ''The Birds''. Rather frightening. Dramatic capture, and nice off-center composition.', '2012-06-23 00:50:57.000000', NULL, 1),
(6800639, 1022243, 66384, '<td valign="top">Very sweet, and such beautiful birds. I really like the colors too -- the way the beaks and the water are the same hue, and the peachy heads are so complementary.</td>', 'Very sweet, and such beautiful birds. I really like the colors too -- the way the beaks and the water are the same hue, and the peachy heads are so complementary.', '2012-06-23 00:57:47.000000', NULL, 1),
(6800640, 1021774, 66384, '<td valign="top">Beautiful bird, and lovely complementary background.</td>', 'Beautiful bird, and lovely complementary background.', '2012-06-23 01:03:03.000000', NULL, 1),
(6800641, 1022286, 66384, '<td valign="top">Ha, that''s fun. Good split second capture.</td>', 'Ha, that''s fun. Good split second capture.', '2012-06-23 01:05:55.000000', NULL, 1),
(6800642, 1022348, 66384, '<td valign="top">Lovely bird and nice background. Needs to be sharper to be a contender.</td>', 'Lovely bird and nice background. Needs to be sharper to be a contender.', '2012-06-23 01:11:23.000000', NULL, 1),
(6800643, 1021446, 66384, '<td valign="top">Interesting how it looks like a bunch of bananas. I don''t care for the border, because it competes with the bird, but I don''t vote based on borders. I would like to see sharper detail in the feathers and eye.</td>', 'Interesting how it looks like a bunch of bananas. I don''t care for the border, because it competes with the bird, but I don''t vote based on borders. I would like to see sharper detail in the feathers and eye.', '2012-06-23 01:18:50.000000', NULL, 1),
(6800644, 1021262, 66384, '<td valign="top">LOL, love the title. Love the shot too!</td>', 'LOL, love the title. Love the shot too!', '2012-06-23 01:20:38.000000', NULL, 1),
(6800645, 1022040, 66384, '<td valign="top">Gorgeous! The colors and the capture are fabulous. The banding in the sky bothers me a little, but not enough to deduct from the score.</td>', 'Gorgeous! The colors and the capture are fabulous. The banding in the sky bothers me a little, but not enough to deduct from the score.', '2012-06-23 01:32:27.000000', NULL, 1),
(6800646, 1022031, 66384, '<td valign="top">Lovely contrast and light.</td>', 'Lovely contrast and light.', '2012-06-23 01:33:11.000000', NULL, 1),
(6800648, 1022281, 113157, '<td valign="top">Wow! I hope you say how you managed to get this shot. 10<strike></strike></td>', 'Wow! I hope you say how you managed to get this shot. 10', '2012-06-23 01:48:52.000000', NULL, 1),
(6800654, 1022365, 67258, '<td valign="top">Funny, but the strong halos around the bird are distracting.</td>', 'Funny, but the strong halos around the bird are distracting.', '2012-06-23 02:30:20.000000', NULL, 1),
(6800655, 1021316, 67258, '<td valign="top">A little too sharpened for my taste, making it uncomfortable for the eye to settle.  The composition is somewhat static - I wonder if a little less centred and more space for the swan to look in to might help?  The placement of the three ducks around the swans head is serendipitous!</td>', 'A little too sharpened for my taste, making it uncomfortable for the eye to settle.  The composition is somewhat static - I wonder if a little less centred and more space for the swan to look in to might help?  The placement of the three ducks around the swans head is serendipitous!', '2012-06-23 02:32:43.000000', NULL, 1),
(6800656, 1022114, 67258, '<td valign="top">This is lovely - thoroughly delightful.</td>', 'This is lovely - thoroughly delightful.', '2012-06-23 02:33:04.000000', NULL, 1),
(6800657, 1022366, 67258, '<td valign="top">Something seems very strange with the water, with the moire type patterns - the flamingo also seems to have developed a rather healthy glow!  Good composition with plenty of room for the bird to move in to.</td>', 'Something seems very strange with the water, with the moire type patterns - the flamingo also seems to have developed a rather healthy glow!  Good composition with plenty of room for the bird to move in to.', '2012-06-23 02:34:39.000000', NULL, 1),
(6800658, 1021652, 67258, '<td valign="top">An interesting take on the challenge, and an appealing photo.  I do find the brightness about 1/3 from left a little too much for comfortable viewing, but nonetheless,  a photo that works for me.</td>', 'An interesting take on the challenge, and an appealing photo.  I do find the brightness about 1/3 from left a little too much for comfortable viewing, but nonetheless,  a photo that works for me.', '2012-06-23 02:36:31.000000', NULL, 1),
(6800660, 1022137, 67258, '<td valign="top">Pleasing to see a photo depicting bird behaviour.  Good timing, perspective composition and exposure technicals.  A little more textural detail in the plumage and you would have had an extra mark.  Nonetheless, a really good entry.</td>', 'Pleasing to see a photo depicting bird behaviour.  Good timing, perspective composition and exposure technicals.  A little more textural detail in the plumage and you would have had an extra mark.  Nonetheless, a really good entry.', '2012-06-23 02:39:00.000000', NULL, 1),
(6800663, 1021351, 67258, '<td valign="top">A heron of some sort?  Quite unlike any I have seen; I love the colours of it''s plumage.  The background bokeh provides the perfect backdrop - my only niggle is the small patch of bright green that has crept in at the left; I would also have preferred just a little more space between the end of the beak and the edge of the frame, but I suspect in this instance you were constrained by distracting (green) elements. Good work!</td>', 'A heron of some sort?  Quite unlike any I have seen; I love the colours of it''s plumage.  The background bokeh provides the perfect backdrop - my only niggle is the small patch of bright green that has crept in at the left; I would also have preferred just a little more space between the end of the beak and the edge of the frame, but I suspect in this instance you were constrained by distracting (green) elements. Good work!', '2012-06-23 02:42:24.000000', NULL, 1),
(6800664, 1022031, 67258, '<td valign="top">Serene and tranquil - perfect exposure on the parent.  Very good photo - and title, too!</td>', 'Serene and tranquil - perfect exposure on the parent.  Very good photo - and title, too!', '2012-06-23 02:43:44.000000', NULL, 1),
(6800665, 1021605, 67258, '<td valign="top">A shame you have just missed the focus.</td>', 'A shame you have just missed the focus.', '2012-06-23 02:44:23.000000', NULL, 1),
(6800666, 1022302, 67258, '<td valign="top">A badly metered flash?  The exposure and processing don''t work at all for me.  Composition is good though.</td>', 'A badly metered flash?  The exposure and processing don''t work at all for me.  Composition is good though.', '2012-06-23 02:45:35.000000', NULL, 1),
(6800671, 1022031, 108580, '<td valign="top">Lovely shot. Whilst I understand the need to heavily UE to get white feather details and a dark BG I think you could have dodged Mum''s face a tad. Great poses on both birds. NickyB?</td>', 'Lovely shot. Whilst I understand the need to heavily UE to get white feather details and a dark BG I think you could have dodged Mum''s face a tad. Great poses on both birds. NickyB?', '2012-06-23 04:11:06.000000', NULL, 1),
(6800678, 1021883, 108580, '<td valign="top">Gorgeous King Very similar to our Giant Kingfisher. Nice crown (is that Gel? hehe), catchlight, crisp, great BG and pose.</td>', 'Gorgeous King Very similar to our Giant Kingfisher. Nice crown (is that Gel? hehe), catchlight, crisp, great BG and pose.', '2012-06-23 04:37:43.000000', NULL, 1),
(6800679, 1022085, 108580, '<td valign="top">Beautiful interactive image of Mom and chick but the bright foreground is distracting my eye.</td>', 'Beautiful interactive image of Mom and chick but the bright foreground is distracting my eye.', '2012-06-23 04:40:36.000000', NULL, 1),
(6800702, 1022299, 74588, '<td valign="top">this could be <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=114285" rel="nofollow" target="_blank">neat</a>   10</td>', 'this could be  neat   10', '2012-06-23 06:56:38.000000', NULL, 1),
(6800708, 1021685, 54446, '<td valign="top">Just a guess, but this might be a huge colony of <a href="//www.skelligsrock.com/wildlife.htm" rel="nofollow" target="_blank">Northern Gannet and many other birds</a> nesting on the cliffs at Little Skellig, near Ireland.  On a revisit to this image, I''m bumping it up because it is amazing. I especially like the birds in the air.  10</td>', 'Just a guess, but this might be a huge colony of Northern Gannet and many other birds nesting on the cliffs at Little Skellig, near Ireland.  On a revisit to this image, I''m bumping it up because it is amazing. I especially like the birds in the air.  10', '2012-06-23 07:56:55.000000', NULL, 1),
(6800723, 1022248, 54446, '<td valign="top">Wonderful kingfisher, but not a species we would see in North America.  Great colors, focus, sharpness, clarity and composition.  Bumping the score now, because I have identified this magnificent birds as a Malachite Kingfisher, <i>Alcedo cristata</i>.  I expect this to be a ribbon contender.  10</td>', 'Wonderful kingfisher, but not a species we would see in North America.  Great colors, focus, sharpness, clarity and composition.  Bumping the score now, because I have identified this magnificent birds as a Malachite Kingfisher, Alcedo cristata.  I expect this to be a ribbon contender.  10', '2012-06-23 08:48:53.000000', NULL, 1),
(6800726, 1022085, 54446, '<td valign="top">Common loon.  Wonderful nature shot of feeding young.  Love it. Bumping this up now to 10.  I expect this to be a top 10.</td>', 'Common loon.  Wonderful nature shot of feeding young.  Love it. Bumping this up now to 10.  I expect this to be a top 10.', '2012-06-23 09:09:30.000000', NULL, 1),
(6800728, 1021950, 114285, '<td valign="top">Lovely processing, unique, just the way I love them to be.</td>', 'Lovely processing, unique, just the way I love them to be.', '2012-06-23 09:23:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6800730, 1021883, 88409, '<td valign="top">Now, I have to comment on this. Love the light. Love the BG. Great detail.<br/>I was going to enter my image of the Belted King (even has same green BG) I''m glad I did not because you did an outstanding  job.  People that never tried shooting this bird will not appreciate this to the full extent.</td>', 'Now, I have to comment on this. Love the light. Love the BG. Great detail.I was going to enter my image of the Belted King (even has same green BG) I''m glad I did not because you did an outstanding  job.  People that never tried shooting this bird will not appreciate this to the full extent.', '2012-06-23 09:41:27.000000', NULL, 1),
(6800778, 1021769, 16046, '<td valign="top">Wow, best in show award, congrats</td>', 'Wow, best in show award, congrats', '2012-06-23 12:49:47.000000', NULL, 1),
(6800779, 1022197, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2012-06-23 12:50:10.000000', NULL, 1),
(6800780, 1022040, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2012-06-23 12:50:30.000000', NULL, 1),
(6800781, 1021412, 16046, '<td valign="top">Top 5</td>', 'Top 5', '2012-06-23 12:50:45.000000', NULL, 1),
(6800782, 1022281, 16046, '<td valign="top">Top 5</td>', 'Top 5', '2012-06-23 12:51:09.000000', NULL, 1),
(6800794, 1021352, 66384, '<td valign="top">Nice clear eye, but I think a deaper DOF would have been better for this shot. I don''t mind the blur on the body, which isolates the face, but I would like to see the whole face in focus.</td>', 'Nice clear eye, but I think a deaper DOF would have been better for this shot. I don''t mind the blur on the body, which isolates the face, but I would like to see the whole face in focus.', '2012-06-23 14:43:45.000000', NULL, 1),
(6800799, 1021769, 66384, '<td valign="top">Nice job on the exposure, and the marvelous reflection. To bad the focus wasn''t sharper, that would have been spectacular.</td>', 'Nice job on the exposure, and the marvelous reflection. To bad the focus wasn''t sharper, that would have been spectacular.', '2012-06-23 14:52:54.000000', NULL, 1),
(6800801, 1021950, 66384, '<td valign="top">Very special. I love the light, color, and composition. Great job of turning an average bird shot into a beautiful image.</td>', 'Very special. I love the light, color, and composition. Great job of turning an average bird shot into a beautiful image.', '2012-06-23 14:57:13.000000', NULL, 1),
(6800808, 1022361, 66384, '<td valign="top">Too bad there''s not more detail in the plumage. There is nice composition and color here.</td>', 'Too bad there''s not more detail in the plumage. There is nice composition and color here.', '2012-06-23 15:11:59.000000', NULL, 1),
(6800812, 1021909, 66384, '<td valign="top">Wonderful detail, light and dark, and strong composition. Great dramatic portrait of a strong bird.</td>', 'Wonderful detail, light and dark, and strong composition. Great dramatic portrait of a strong bird.', '2012-06-23 15:15:57.000000', NULL, 1),
(6800817, 1021268, 68504, '<td valign="top">this gives me enormous pleasure.</td>', 'this gives me enormous pleasure.', '2012-06-23 15:41:59.000000', NULL, 1),
(6800821, 1022296, 67258, '<td valign="top">An interesting idea, but I feel that you haven''t entirely pulled it off.  The lighting, on the bird in particular is somewhat harsh with parts in deep shadow and others a little too bright.  Worth experimenting more though, and I would have been delighted to have enticed a bird into my set-up.</td>', 'An interesting idea, but I feel that you haven''t entirely pulled it off.  The lighting, on the bird in particular is somewhat harsh with parts in deep shadow and others a little too bright.  Worth experimenting more though, and I would have been delighted to have enticed a bird into my set-up.', '2012-06-23 15:55:39.000000', NULL, 1),
(6800822, 1022116, 67258, '<td valign="top">A little over-sharpened, but what a delightfully fierce little bird you have photographed - made me smile.</td>', 'A little over-sharpened, but what a delightfully fierce little bird you have photographed - made me smile.', '2012-06-23 15:56:32.000000', NULL, 1),
(6800824, 1022032, 67258, '<td valign="top">Probably not shot at the most conducive time of day, the lighting is very harsh.  I would have preferred either e tighter crop into just the head and body, or looser so that the tail feathers and legs weren''t cut off.</td>', 'Probably not shot at the most conducive time of day, the lighting is very harsh.  I would have preferred either e tighter crop into just the head and body, or looser so that the tail feathers and legs weren''t cut off.', '2012-06-23 15:58:41.000000', NULL, 1),
(6800826, 1022324, 67258, '<td valign="top">Strong shadow and a detailed back ground detract, but, for me, an interesting and alien bird.</td>', 'Strong shadow and a detailed back ground detract, but, for me, an interesting and alien bird.', '2012-06-23 15:59:57.000000', NULL, 1),
(6800827, 1021951, 67258, '<td valign="top">Good exposure and technicals. The photo is a little static for my taste - I would have preferred a little more space to the right.</td>', 'Good exposure and technicals. The photo is a little static for my taste - I would have preferred a little more space to the right.', '2012-06-23 16:01:14.000000', NULL, 1),
(6800828, 1022085, 67258, '<td valign="top">I do like nature photographs that tell a story, and you have certainly achieved that here.  Interesting bird, too, certainly not one we get in the UK.  Is it related to the coot and moorhen, I wonder?</td>', 'I do like nature photographs that tell a story, and you have certainly achieved that here.  Interesting bird, too, certainly not one we get in the UK.  Is it related to the coot and moorhen, I wonder?', '2012-06-23 16:03:11.000000', NULL, 1),
(6800829, 1021542, 67258, '<td valign="top">Black and white works well here.  Nicely set off against the background, the nest adding context.  Good work.</td>', 'Black and white works well here.  Nicely set off against the background, the nest adding context.  Good work.', '2012-06-23 16:03:56.000000', NULL, 1),
(6800830, 1022197, 67258, '<td valign="top">Pretty, delicate photo.  The striped background is a negative for me, though.</td>', 'Pretty, delicate photo.  The striped background is a negative for me, though.', '2012-06-23 16:04:41.000000', NULL, 1),
(6800831, 1021352, 67258, '<td valign="top">Well, that''s up close and personal!  Can''t fault your focus, but subjectively, I would have preferred a slightly deeper depth of field allowing for the beak to remain in focus too.</td>', 'Well, that''s up close and personal!  Can''t fault your focus, but subjectively, I would have preferred a slightly deeper depth of field allowing for the beak to remain in focus too.', '2012-06-23 16:06:21.000000', NULL, 1),
(6800832, 1021814, 67258, '<td valign="top">I looove puffins, and am holiday now so that I can go and visit some - a few days too late for this challenge (although I was able to get a distant photo of one).  I like the rich, velvetiness of the water, and I LOVE the reflection - I have never seen that before.  A shame you weren''t able to get a bit more detail, but I suspect that you were at the very end reach of your ens and probably cropped in quite a way in post processing.  Still, that reflection is cracking, and adds a quite different element to your photo.</td>', 'I looove puffins, and am holiday now so that I can go and visit some - a few days too late for this challenge (although I was able to get a distant photo of one).  I like the rich, velvetiness of the water, and I LOVE the reflection - I have never seen that before.  A shame you weren''t able to get a bit more detail, but I suspect that you were at the very end reach of your ens and probably cropped in quite a way in post processing.  Still, that reflection is cracking, and adds a quite different element to your photo.', '2012-06-23 16:09:53.000000', NULL, 1),
(6800835, 1021867, 66384, '<td valign="top">Beautiful clarity and just the right DOF. I would rather have seen this without the mouse, but then it would have been just a very good portrait. I think the drama of this will probably place it very high in the ranking.</td>', 'Beautiful clarity and just the right DOF. I would rather have seen this without the mouse, but then it would have been just a very good portrait. I think the drama of this will probably place it very high in the ranking.', '2012-06-23 16:59:13.000000', NULL, 1),
(6800838, 1022290, 103142, '<td valign="top">Well, fine then! I''m not voting on yours either!!<br/> <br/>(which is a shame, because I like him. :)<br/> <br/>I do think we should have brought him home, however. :)</td>', 'Well, fine then! I''m not voting on yours either!! (which is a shame, because I like him. :) I do think we should have brought him home, however. :)', '2012-06-23 18:23:57.000000', NULL, 1),
(6800840, 1022197, 103142, '<td valign="top">Beautiful capture. I''m curious what the background is -- the horizontal lines are kind of odd...<br/> <br/>Anyway, nicely done! -8-</td>', 'Beautiful capture. I''m curious what the background is -- the horizontal lines are kind of odd... Anyway, nicely done! -8-', '2012-06-23 18:26:43.000000', NULL, 1),
(6800841, 1022156, 103142, '<td valign="top">Fun image -- I like the tight crop. You have some weird banding around the tree, though. Doesn''t matter to me, though, because I love the fun in the shot. :)  -8-</td>', 'Fun image -- I like the tight crop. You have some weird banding around the tree, though. Doesn''t matter to me, though, because I love the fun in the shot. :)  -8-', '2012-06-23 18:26:46.000000', NULL, 1),
(6800842, 1022363, 103142, '<td valign="top">wow... seriously? Cool shot! By itself, the shot of the bird is just kind of "meh" (sorry!) because he''s in such a weird pose (I know... birds don''t pose ;), but the combination and the textures make for a very interesting picture. -8-</td>', 'wow... seriously? Cool shot! By itself, the shot of the bird is just kind of "meh" (sorry!) because he''s in such a weird pose (I know... birds don''t pose ;), but the combination and the textures make for a very interesting picture. -8-', '2012-06-23 18:26:50.000000', NULL, 1),
(6800843, 1021605, 103142, '<td valign="top">Love this shot! The focus is a bit off, it''s on the grass instead of the bird, but for some reason I don''t care. I love the environment. -8-</td>', 'Love this shot! The focus is a bit off, it''s on the grass instead of the bird, but for some reason I don''t care. I love the environment. -8-', '2012-06-23 18:26:53.000000', NULL, 1),
