(6804181, 1021769, 81362, '<td valign="top">So now you rule the roost with the highest score ever using a  <a href="//www.dpchallenge.com/camera.php?CAMERA_ID=1917" rel="nofollow" target="_blank">Canon EOS-7D</a>, and you''ve nailed the 13th highest score so far on DPC''s <a href="//www.dpchallenge.com/photo_browse.php?view=highestrated" rel="nofollow" target="_blank">Browse Highest Rated</a> page. Good for you: well-deserved.</td>', 'So now you rule the roost with the highest score ever using a  Canon EOS-7D, and you''ve nailed the 13th highest score so far on DPC''s Browse Highest Rated page. Good for you: well-deserved.', '2012-06-29 05:37:51.000000', NULL, 0),
